import { Schema } from "prosemirror-model";
import { EditorState } from "prosemirror-state";
import { EditorView } from "prosemirror-view";
import { schema as basicSchema } from "prosemirror-schema-basic";
import { history, undo, redo } from "prosemirror-history";
import { keymap } from "prosemirror-keymap";
import { baseKeymap } from "prosemirror-commands";
import {
  createMathPlugin,
  insertMath,
  mathNodes,
} from "@barocss/math-editor-prosemirror";
import type { MathIntegrationOptions } from "@barocss/math-editor-prosemirror/shared";
import {
  initialDocument,
  withProseMirrorHandles,
} from "./prosemirror-shared.js";
import "prosemirror-view/style/prosemirror.css";

export async function mountProseMirrorDemo(
  host: HTMLElement,
  options: MathIntegrationOptions
) {
  const listeners = new Set<() => void>();
  const schema = new Schema({
    nodes: basicSchema.spec.nodes.append(mathNodes),
    marks: basicSchema.spec.marks,
  });
  const plugins = () => [
    createMathPlugin(options),
    history(),
    keymap({ "Mod-z": undo, "Mod-Shift-z": redo, "Mod-y": redo }),
    keymap(baseKeymap),
  ];
  const view = new EditorView(host, {
    state: EditorState.create({
      schema,
      doc: schema.nodeFromJSON(initialDocument(options.locale === "en")),
      plugins: plugins(),
    }),
    dispatchTransaction(tr) {
      view.updateState(view.state.apply(tr));
      if (tr.docChanged) listeners.forEach((listener) => listener());
    },
  });
  return withProseMirrorHandles({
    view,
    getData: () => view.state.doc.toJSON(),
    setData(data: unknown) {
      view.updateState(
        EditorState.create({
          schema,
          doc: schema.nodeFromJSON(data),
          plugins: plugins(),
        })
      );
      listeners.forEach((listener) => listener());
    },
    insert(kind) {
      insertMath("", kind)(view.state, view.dispatch);
      view.focus();
    },
    undo: () => {
      undo(view.state, view.dispatch);
    },
    redo: () => {
      redo(view.state, view.dispatch);
    },
    setReadOnly: (value) => view.setProps({ editable: () => !value }),
    onChange(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    destroy() {
      listeners.clear();
      view.destroy();
    },
  });
}
