  const atom = document.createElement("span");
  const attrs = mathAttributes("a^2+b^2=c^2", "inline")!;
  atom.dataset.barocssMath = "inline";
  atom.dataset.latex = attrs.latex;
  atom.dataset.mathDocument = JSON.stringify(attrs.mathDocument);
  atom.dataset.mathSize = "100";
  atom.contentEditable = "false";
  atom.textContent = attrs.latex;
  p.append(atom, ". Continue writing here.");
  editable.append(p);
  host.append(editable);
