import { BarocssMath } from "@barocss/math-editor-tiptap";
import type { MathIntegrationOptions } from "@barocss/math-editor-tiptap/shared";
import {
  initialDocument,
  withProseMirrorHandles,
} from "./prosemirror-shared.js";
import "prosemirror-view/style/prosemirror.css";

export async function mountTiptapDemo(
  host: HTMLElement,
  options: MathIntegrationOptions
) {
  const listeners = new Set<() => void>();
  const editor = new Editor({
    element: host,
    extensions: [StarterKit, BarocssMath.configure(options)],
    content: initialDocument(options.locale === "en"),
    onUpdate: () => listeners.forEach((listener) => listener()),
  });
  return withProseMirrorHandles({
    view: editor.view,
    getData: () => editor.getJSON(),
    setData: (data: unknown) => {
      // Loading a document is one history operation. A quick subsequent edit
      // must not merge with it and undo the restored document together with text.
      const boundary = () =>
        editor.view.dispatch(
          closeHistory(editor.state.tr).setMeta("addToHistory", false)
        );
      boundary();
      editor.commands.setContent(data as ReturnType<typeof initialDocument>);
      boundary();
    },
    insert: (kind) => {
      editor.chain().focus().insertMath("", kind).run();
    },
    undo: () => {
      editor.commands.undo();
    },
    redo: () => {
      editor.commands.redo();
    },
    setReadOnly: (value) => editor.setEditable(!value),
    onChange(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    destroy() {
      listeners.clear();
      editor.destroy();
    },
  });
}
